mapper.select:
SELECT COUNT(*) FROM dimension_comment c
    INNER JOIN dimension_image i ON i.id = c.image_id
WHERE i.user_id = #{userId} AND c.user_id != #{userId} AND c.id > #{sinceId}

SELECT COUNT(*) FROM dimension_comment c
WHERE c.content LIKE CONCAT('%@', #{nickname}, '%')
  AND c.user_id != #{userId} AND c.id > #{sinceId}

SELECT COUNT(*) FROM dimension_image i
    INNER JOIN dimension_follow f ON f.followed_user_id = i.user_id
WHERE f.user_id = #{userId} AND i.status = 1 AND i.id > #{sinceId}

SELECT * FROM ( SELECT 'PRIVATE' AS type, m.id AS refId, m.sender_id AS actorId, u.nickname AS actorName, u.avatar AS actorAvatar, NULL AS title, m.content AS content, NULL AS imageId, m.create_time AS createTime, m.is_read AS isReadFlag FROM dimension_message m LEFT JOIN dimension_user u ON u.id = m.sender_id WHERE m.receiver_id = #{userId}
UNION ALL
SELECT 'REPLY', c.id, c.user_id, u.nickname, u.avatar, NULL, c.content, c.image_id, c.create_time, 1 FROM dimension_comment c INNER JOIN dimension_image i ON i.id = c.image_id LEFT JOIN dimension_user u ON u.id = c.user_id WHERE i.user_id = #{userId} AND c.user_id != #{userId}
UNION ALL
SELECT 'MENTION', c.id, c.user_id, u.nickname, u.avatar, NULL, c.content, c.image_id, c.create_time, 1 FROM dimension_comment c LEFT JOIN dimension_user u ON u.id = c.user_id WHERE c.content LIKE CONCAT('%@', #{nickname}, '%') AND c.user_id != #{userId} ) t ORDER BY t.createTime DESC LIMIT #{pageNum}, #{pageSize}

SELECT * FROM ( SELECT 'ANNOUNCE' AS type, n.id AS refId, NULL AS actorId, '系统公告' AS actorName, NULL AS actorAvatar, n.title AS title, n.content AS content, NULL AS imageId, n.create_time AS createTime FROM dimension_notice n
UNION ALL
SELECT 'WORK_UPDATE', i.id, i.user_id, u.nickname, u.avatar, NULL, NULL, i.id, i.create_time FROM dimension_image i INNER JOIN dimension_follow f ON f.followed_user_id = i.user_id LEFT JOIN dimension_user u ON u.id = i.user_id WHERE f.user_id = #{userId} AND i.status = 1 ) t ORDER BY t.createTime DESC LIMIT #{pageNum}, #{pageSize}

SELECT COALESCE(MAX(c.id), 0) FROM dimension_comment c
    INNER JOIN dimension_image i ON i.id = c.image_id
WHERE i.user_id = #{userId} AND c.user_id != #{userId}
